<script setup>
import{onMounted,ref}from'vue';import{api}from'../services/api';import{config}from'../config';import{useJob}from'../composables/useJob';import JobStatus from '../components/JobStatus.vue';const preflight=ref(null),status=ref('');const{job,refresh}=useJob();onMounted(async()=>{preflight.value=await api.preflight();refresh()});async function exportZip(){status.value=(await api.exportPackage()).message||'Exportación iniciada.';refresh()}
</script>
<template><section class="hero"><span class="eyebrow">VALIDACIÓN Y ENTREGA</span><h2>Preflight y ZIP NIMAS</h2><p>El paquete solo se crea después de validar las lecciones, metadata, recursos, DTBook y OPF.</p></section><JobStatus :job="job"/><section class="library-card"><h3>Resultado del preflight</h3><strong :class="preflight?.status==='pass'?'pass':'fail'">{{preflight?.status||'Consultando…'}}</strong><ul><li v-for="check in preflight?.checks" :class="check.ok?'ok':'bad'">{{check.ok?'✓':'!'}} {{check.message}}</li></ul><button :disabled="preflight?.status!=='pass'||job?.running" @click="exportZip">Crear ZIP validado</button><p class="hint">{{status}}</p><a v-if="job?.export?.zip" class="download-link" :href="config.static('/'+job.export.zip)" download>Descargar ZIP validado</a></section></template>
